const a = 3 + 2.39996 * seed, b = 0.88 + 3.88322 * seed; // the bends' phases, a golden angle further per seed
const zc = size * (0.11 * sin(TAU * 0.85 * x / size + a) + 0.045 * sin(TAU * 1.9 * x / size + b));
return smoothstep(0.03, 0.4, abs(z - zc) / size);

// where gullies reach the floor: water of 20 to 2000 cells at the foot of the walls (a 0..1 mask here, metres later)
const n = Math.log(1 + (Math.exp(drainage) - 1) / (cell * cell));
return smoothstep(3, 5.5, n) * (1 - smoothstep(7.5, 9.5, n)) * (1 - smoothstep(0.02, 0.15, mask));

// gullies on the walls where the water of 7 to 1100 cells gathers
const cells = (Math.exp(drainage) - 1) / (cell * cell);
return smoothstep(2, 7, Math.log(1 + cells)) * smoothstep(0.05, 0.4, mask);

