params.code:
// the river bed: the eroded floor under the course, smoothed along it, then made to fall all the way, river_depth below
const n = Math.round(Math.sqrt(npoints(1))), o = point(1, 'P', 0), cell = point(1, 'P', 1)[0] - o[0];
const ground = (px, pz) => {
  const fx = (px - o[0]) / cell, fz = (pz - o[2]) / cell;
  const i = clamp(Math.floor(fx), 0, n - 2), j = clamp(Math.floor(fz), 0, n - 2), u = clamp(fx - i, 0, 1), v = clamp(fz - j, 0, 1);
  const h = (a, b) => point(1, 'P', (j + b) * n + i + a)[1];
  return (h(0, 0) * (1 - u) + h(1, 0) * u) * (1 - v) + (h(0, 1) * (1 - u) + h(1, 1) * u) * v;
};
const pts = primpoints(0, 0), P = pts.map((p) => point(0, 'P', p)), m = P.length;
const floor = P.map((q) => ground(q[0], q[2]));
const k = 6, smooth = floor.map((_, i) => { let s = 0, c = 0; for (let d = -k; d <= k; d++) { const y = floor[clamp(i + d, 0, m - 1)]; s += y; c++; } return s / c; });
const drop = 0.002; // the least fall per metre
let y = smooth[0];
for (let i = 0; i < m; i++) {
  if (i > 0) y = Math.min(smooth[i], y - drop * distance(P[i], P[i - 1]));
  setpointattrib(0, 'P', pts[i], [P[i][0], y - river_depth, P[i][2]]);
}

